  1	package com.marealta;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import io.javalin.Javalin;
  6	import io.javalin.http.Context;
  7	import java.time.LocalDate;
  8	import java.time.YearMonth;
  9	import java.time.format.DateTimeParseException;
 10	import java.util.LinkedHashMap;
 11	import java.util.List;
 12	import java.util.Map;
 13	
 14	public final class App {
 15	    private static final ObjectMapper JSON = new ObjectMapper();
 16	
 17	    private final ReservationService service;
 18	
 19	    public App(ReservationService service) {
 20	        this.service = service;
 21	    }
 22	
 23	    public Javalin create() {
 24	        Javalin app = Javalin.create();
 25	        app.get("/rooms", ctx -> json(ctx, 200, service.rooms().stream().map(App::roomView).toList()));
 26	        app.post("/reservations", ctx -> json(ctx, 201, view(service.create(parseNew(ctx.body())))));
 27	        app.get("/reservations/{id}", ctx -> json(ctx, 200, view(service.get(id(ctx)))));
 28	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, view(service.confirm(id(ctx)))));
 29	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, view(service.cancel(id(ctx)))));
 30	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, view(service.checkIn(id(ctx)))));
 31	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, service.checkOut(id(ctx))));
 32	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, service.document(id(ctx))));
 33	        app.get("/messages", ctx -> json(ctx, 200, service.messages().stream().map(App::messageView).toList()));
 34	        app.get("/reports/occupancy", ctx -> csv(ctx, service.occupancyReport(queryDate(ctx, "date"))));
 35	        app.get("/reports/revenue", ctx -> csv(ctx, service.revenueReport(queryMonth(ctx, "month"))));
 36	
 37	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
 38	        app.exception(Exception.class, (e, ctx) -> {
 39	            e.printStackTrace();
 40	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 41	        });
 42	        app.error(404, ctx -> {
 43	            if (ctx.result() == null || ctx.result().isEmpty()) error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
 44	        });
 45	        return app;
 46	    }
 47	
 48	    // ---- respostas
 49	
 50	    private static void json(Context ctx, int status, Object body) throws Exception {
 51	        ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
 52	    }
 53	
 54	    private static void csv(Context ctx, String body) {
 55	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
 56	    }
 57	
 58	    private static void error(Context ctx, int status, String code, String message) {
 59	        Map<String, Object> body = new LinkedHashMap<>();
 60	        body.put("error", code);
 61	        body.put("message", message);
 62	        try {
 63	            json(ctx, status, body);
 64	        } catch (Exception e) {
 65	            ctx.status(status);
 66	        }
 67	    }
 68	
 69	    private static Map<String, Object> roomView(Room r) {
 70	        Map<String, Object> m = new LinkedHashMap<>();
 71	        m.put("number", r.number());
 72	        m.put("type", r.type());
 73	        m.put("capacity", r.capacity());
 74	        m.put("nightlyRate", r.nightlyRate());
 75	        return m;
 76	    }
 77	
 78	    private static Map<String, Object> messageView(Message x) {
 79	        Map<String, Object> m = new LinkedHashMap<>();
 80	        m.put("id", x.id());
 81	        m.put("channel", x.channel());
 82	        m.put("to", x.to());
 83	        m.put("subject", x.subject());
 84	        m.put("body", x.body());
 85	        return m;
 86	    }
 87	
 88	    private static Map<String, Object> view(Reservation r) {
 89	        Map<String, Object> m = new LinkedHashMap<>();
 90	        m.put("id", r.id());
 91	        m.put("roomNumber", r.roomNumber());
 92	        m.put("guestName", r.guestName());
 93	        m.put("guestEmail", r.guestEmail());
 94	        m.put("guestCpf", r.guestCpf());
 95	        m.put("checkIn", r.checkIn().toString());
 96	        m.put("checkOut", r.checkOut().toString());
 97	        m.put("guests", r.guests());
 98	        m.put("ratePlan", r.ratePlan());
 99	        m.put("companyCode", r.companyCode());
100	        m.put("nights", r.nights());
101	        m.put("subtotal", r.subtotal());
102	        m.put("discount", r.discount());
103	        m.put("total", r.total());
104	        m.put("status", r.status());
105	        m.put("amountPaid", r.amountPaid());
106	        m.put("refund", r.refund());
107	        return m;
108	    }
109	
110	    // ---- entrada
111	
112	    private static long id(Context ctx) {
113	        String raw = ctx.pathParam("id");
114	        try {
115	            return Long.parseLong(raw);
116	        } catch (NumberFormatException e) {
117	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada: " + raw);
118	        }
119	    }
120	
121	    private static LocalDate queryDate(Context ctx, String name) {
122	        String v = ctx.queryParam(name);
123	        if (v == null) throw ApiException.invalid("Parâmetro obrigatório: " + name);
124	        return date(v, name);
125	    }
126	
127	    private static YearMonth queryMonth(Context ctx, String name) {
128	        String v = ctx.queryParam(name);
129	        if (v == null) throw ApiException.invalid("Parâmetro obrigatório: " + name);
130	        if (!v.matches("\\d{4}-\\d{2}")) throw ApiException.invalid("Mês inválido (use AAAA-MM): " + v);
131	        try {
132	            return YearMonth.parse(v);
133	        } catch (DateTimeParseException e) {
134	            throw ApiException.invalid("Mês inválido (use AAAA-MM): " + v);
135	        }
136	    }
137	
138	    private static LocalDate date(String v, String field) {
139	        try {
140	            return LocalDate.parse(v);
141	        } catch (DateTimeParseException e) {
142	            throw ApiException.invalid("Data inválida em " + field + " (use AAAA-MM-DD): " + v);
143	        }
144	    }
145	
146	    static ReservationService.NewReservation parseNew(String body) {
147	        JsonNode root;
148	        try {
149	            root = JSON.readTree(body);
150	        } catch (Exception e) {
151	            throw ApiException.invalid("O corpo deve ser um JSON válido");
152	        }
153	        if (root == null || !root.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
154	
155	        int roomNumber = integer(root, "roomNumber");
156	        String name = text(root, "guestName");
157	        String email = text(root, "guestEmail");
158	        String cpf = text(root, "guestCpf");
159	        LocalDate in = date(text(root, "checkIn"), "checkIn");
160	        LocalDate out = date(text(root, "checkOut"), "checkOut");
161	        int guests = integer(root, "guests");
162	        String plan = text(root, "ratePlan");
163	        JsonNode cc = root.get("companyCode");
164	        String company = cc != null && cc.isTextual() ? cc.asText() : null;
165	
166	        if (!out.isAfter(in)) throw ApiException.invalid("A saída deve ser depois da entrada");
167	        if (guests < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
168	        return new ReservationService.NewReservation(roomNumber, name.trim(), email.trim(), cpf.trim(), in, out,
169	                guests, plan.trim(), company);
170	    }
171	
172	    private static String text(JsonNode root, String field) {
173	        JsonNode n = root.get(field);
174	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
175	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
176	        }
177	        return n.asText();
178	    }
179	
180	    private static int integer(JsonNode root, String field) {
181	        JsonNode n = root.get(field);
182	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
183	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
184	        }
185	        return n.asInt();
186	    }
187	}
188	package com.marealta;
189	
190	public final class Main {
191	    public static void main(String[] args) {
192	        String url = System.getenv("DB_URL");
193	        if (url == null || url.isBlank()) {
194	            System.err.println("A variável de ambiente DB_URL é obrigatória");
195	            System.exit(1);
196	        }
197	        Db db = Db.connect(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
198	        db.migrate();
199	        String port = System.getenv("PORT");
200	        new App(new ReservationService(db)).create().start(port == null || port.isBlank() ? 7070 : Integer.parseInt(port));
201	    }
202	}
203	package com.marealta;
204	
205	/** Erro de negócio/validação que vira { "error": code, "message": ... } com o status HTTP indicado. */
206	public class ApiException extends RuntimeException {
207	    private final int status;
208	    private final String code;
209	
210	    public ApiException(int status, String code, String message) {
211	        super(message);
212	        this.status = status;
213	        this.code = code;
214	    }
215	
216	    public static ApiException invalid(String message) {
217	        return new ApiException(400, "INVALID_REQUEST", message);
218	    }
219	
220	    public int status() { return status; }
221	    public String code() { return code; }
222	}

