  1	package com.marealta;
  2	
  3	import com.marealta.plan.BookingTerms;
  4	import com.marealta.plan.Quote;
  5	import com.marealta.plan.RatePlan;
  6	import com.marealta.plan.RatePlans;
  7	import java.sql.Connection;
  8	import java.sql.SQLException;
  9	import java.time.LocalDate;
 10	import java.time.YearMonth;
 11	import java.util.List;
 12	
 13	public final class ReservationService {
 14	    public static final String EMAIL_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
 15	
 16	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 17	                                 LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan,
 18	                                 String companyCode) {}
 19	
 20	    private final Db db;
 21	
 22	    public ReservationService(Db db) {
 23	        this.db = db;
 24	    }
 25	
 26	    public List<Room> rooms() {
 27	        return db.tx(Store::rooms);
 28	    }
 29	
 30	    public List<Message> messages() {
 31	        return db.tx(Store::messages);
 32	    }
 33	
 34	    public Reservation create(NewReservation n) {
 35	        RatePlan plan = RatePlans.find(n.ratePlan())
 36	                .orElseThrow(() -> ApiException.invalid("Plano de tarifa desconhecido: " + n.ratePlan()));
 37	        return db.tx(c -> {
 38	            Room room = Store.lockRoom(c, n.roomNumber())
 39	                    .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto não encontrado: " + n.roomNumber()));
 40	            Quote q = plan.quote(new BookingTerms(room, n.checkIn(), n.checkOut(), n.companyCode()));
 41	            if (n.guests() > room.capacity()) {
 42	                throw new ApiException(422, "CAPACITY_EXCEEDED",
 43	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
 44	            }
 45	            if (Store.hasConflict(c, room.number(), n.checkIn(), n.checkOut())) {
 46	                throw new ApiException(409, "ROOM_UNAVAILABLE", "O quarto já está reservado em alguma das noites");
 47	            }
 48	            String company = "CORPORATE".equals(plan.code()) ? n.companyCode().trim() : null;
 49	            return Store.insert(c, new Reservation(0, room.number(), n.guestName(), n.guestEmail(), n.guestCpf(),
 50	                    n.checkIn(), n.checkOut(), n.guests(), plan.code(), company, q.nights(), q.subtotal(), q.discount(),
 51	                    q.total(), ReservationStatus.PENDING, Money.ZERO, null));
 52	        });
 53	    }
 54	
 55	    public Reservation get(long id) {
 56	        return db.tx(c -> load(c, id, false));
 57	    }
 58	
 59	    public Reservation confirm(long id) {
 60	        return db.tx(c -> {
 61	            Reservation r = load(c, id, true);
 62	            require(r, r.status() == ReservationStatus.PENDING, "confirmar");
 63	            Reservation paid = withState(r, ReservationStatus.CONFIRMED, r.total(), null);
 64	            Store.updateState(c, paid);
 65	            Receipt receipt = receipt(c, paid);
 66	            Store.insertMessage(c, new Message(0, "EMAIL", paid.guestEmail(), EMAIL_SUBJECT,
 67	                    "Olá, " + paid.guestName() + "!\n\n"
 68	                            + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
 69	                            + receipt.text() + "\n\n"
 70	                            + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
 71	                            + "Até breve!"));
 72	            return paid;
 73	        });
 74	    }
 75	
 76	    public Reservation cancel(long id) {
 77	        return db.tx(c -> {
 78	            Reservation r = load(c, id, true);
 79	            require(r, r.status() == ReservationStatus.PENDING || r.status() == ReservationStatus.CONFIRMED, "cancelar");
 80	            Reservation done = withState(r, ReservationStatus.CANCELLED, r.amountPaid(),
 81	                    RatePlans.require(r.ratePlan()).refund(r.amountPaid()));
 82	            Store.updateState(c, done);
 83	            return done;
 84	        });
 85	    }
 86	
 87	    public Reservation checkIn(long id) {
 88	        return db.tx(c -> {
 89	            Reservation r = load(c, id, true);
 90	            require(r, r.status() == ReservationStatus.CONFIRMED, "fazer check-in");
