185	        try (PreparedStatement ps = c.prepareStatement(
186	                "SELECT number,type,capacity,nightly_rate FROM rooms WHERE number=? FOR UPDATE")) {
187	            ps.setInt(1, number);
188	            try (ResultSet r = ps.executeQuery()) {
189	                return r.next() ? Optional.of(room(r)) : Optional.empty();
190	            }
191	        }
192	    }
