195	        try (PreparedStatement ps = c.prepareStatement(
196	                "SELECT 1 FROM reservations WHERE room_number=? AND status<>'CANCELLED' AND check_in<? AND check_out>? LIMIT 1")) {
197	            ps.setInt(1, roomNumber);
198	            ps.setDate(2, Date.valueOf(out));
199	            ps.setDate(3, Date.valueOf(in));
200	            try (ResultSet r = ps.executeQuery()) {
201	                return r.next();
202	            }
203	        }
204	    }
