207	        try (PreparedStatement ps = c.prepareStatement(
208	                "INSERT INTO reservations(room_number,guest_name,guest_email,guest_cpf,check_in,check_out,guests,rate_plan,"
209	                        + "company_code,nights,subtotal,discount,total,status,amount_paid,refund) "
210	                        + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id")) {
211	            ps.setInt(1, v.roomNumber());
212	            ps.setString(2, v.guestName());
213	            ps.setString(3, v.guestEmail());
214	            ps.setString(4, v.guestCpf());
215	            ps.setDate(5, Date.valueOf(v.checkIn()));
216	            ps.setDate(6, Date.valueOf(v.checkOut()));
217	            ps.setInt(7, v.guests());
218	            ps.setString(8, v.ratePlan());
219	            ps.setString(9, v.companyCode());
220	            ps.setInt(10, v.nights());
221	            ps.setBigDecimal(11, v.subtotal());
222	            ps.setBigDecimal(12, v.discount());
223	            ps.setBigDecimal(13, v.total());
224	            ps.setString(14, v.status().name());
225	            ps.setBigDecimal(15, v.amountPaid());
226	            ps.setBigDecimal(16, v.refund());
227	            try (ResultSet r = ps.executeQuery()) {
228	                r.next();
229	                return find(c, r.getLong(1), false).orElseThrow();
230	            }
231	        }
232	    }
