234	    private static Reservation reservation(ResultSet r) throws SQLException {
235	        return new Reservation(r.getLong(1), r.getInt(2), r.getString(3), r.getString(4), r.getString(5),
236	                r.getDate(6).toLocalDate(), r.getDate(7).toLocalDate(), r.getInt(8), r.getString(9), r.getString(10),
237	                r.getInt(11), r.getBigDecimal(12), r.getBigDecimal(13), r.getBigDecimal(14),
238	                ReservationStatus.valueOf(r.getString(15)), r.getBigDecimal(16), r.getBigDecimal(17));
239	    }
