241	    public static Optional<Reservation> find(Connection c, long id, boolean lock) throws SQLException {
242	        try (PreparedStatement ps = c.prepareStatement(
243	                "SELECT " + RES_COLS + " FROM reservations WHERE id=?" + (lock ? " FOR UPDATE" : ""))) {
244	            ps.setLong(1, id);
245	            try (ResultSet r = ps.executeQuery()) {
246	                return r.next() ? Optional.of(reservation(r)) : Optional.empty();
247	            }
248	        }
249	    }
