251	    public static void updateState(Connection c, Reservation v) throws SQLException {
252	        try (PreparedStatement ps = c.prepareStatement(
253	                "UPDATE reservations SET status=?, amount_paid=?, refund=? WHERE id=?")) {
254	            ps.setString(1, v.status().name());
255	            ps.setBigDecimal(2, v.amountPaid());
256	            ps.setBigDecimal(3, v.refund());
257	            ps.setLong(4, v.id());
258	            ps.executeUpdate();
259	        }
260	    }
