262	    /** Reservas com entrada em [from, to), por data de entrada e número. */
263	    public static List<Reservation> startingBetween(Connection c, LocalDate from, LocalDate to) throws SQLException {
264	        return query(c, "check_in>=? AND check_in<?", "check_in, id", from, to);
265	    }
