267	    /** Reservas cuja estadia cobre a noite dada (entrada <= noite < saída). */
268	    public static List<Reservation> coveringNight(Connection c, LocalDate night) throws SQLException {
269	        return query(c, "check_in<=? AND check_out>?", "room_number, id", night, night);
270	    }
