272	    private static List<Reservation> query(Connection c, String where, String order, LocalDate a, LocalDate b)
273	            throws SQLException {
274	        try (PreparedStatement ps = c.prepareStatement(
275	                "SELECT " + RES_COLS + " FROM reservations WHERE " + where + " ORDER BY " + order)) {
276	            ps.setDate(1, Date.valueOf(a));
277	            ps.setDate(2, Date.valueOf(b));
278	            try (ResultSet r = ps.executeQuery()) {
279	                List<Reservation> out = new ArrayList<>();
