314	import javax.sql.DataSource;
315	
316	public final class Db {
317	    @FunctionalInterface
318	    public interface Work<T> {
319	        T run(Connection c) throws SQLException;
320	    }
321	
322	    private final DataSource ds;
323	
324	    public Db(DataSource ds) {
325	        this.ds = ds;
326	    }
327	
328	    public static Db connect(String url, String user, String password) {
329	        HikariConfig cfg = new HikariConfig();
330	        cfg.setJdbcUrl(url);
331	        cfg.setUsername(user);
332	        cfg.setPassword(password);
333	        cfg.setMaximumPoolSize(10);
334	        cfg.setInitializationFailTimeout(60_000); // espera o banco subir
335	        return new Db(new HikariDataSource(cfg));
336	    }
337	
338	    /** Executa o trabalho numa transação: commit se terminar, rollback se lançar exceção. */
339	    public <T> T tx(Work<T> work) {
340	        try (Connection c = ds.getConnection()) {
341	            c.setAutoCommit(false);
342	            try {
343	                T result = work.run(c);
344	                c.commit();
345	                return result;
346	            } catch (RuntimeException | SQLException | Error e) {
347	                c.rollback();
348	                throw e;
349	            }
350	        } catch (SQLException e) {
351	            throw new IllegalStateException("Erro de banco de dados", e);
352	        }
353	    }
354	
355	    /** Cria o que o sistema precisa num banco vazio (idempotente). */
356	    public void migrate() {
357	        tx(c -> {
358	            try (Statement s = c.createStatement()) {
359	                s.execute("SELECT pg_advisory_xact_lock(7070)");
360	                s.execute("""
361	                        CREATE TABLE IF NOT EXISTS rooms (
362	                          number INTEGER PRIMARY KEY,
363	                          type TEXT NOT NULL,
364	                          capacity INTEGER NOT NULL,
365	                          nightly_rate NUMERIC(12,2) NOT NULL)""");
366	                s.execute("""
367	                        CREATE TABLE IF NOT EXISTS reservations (
368	                          id BIGSERIAL PRIMARY KEY,
369	                          room_number INTEGER NOT NULL REFERENCES rooms(number),
370	                          guest_name TEXT NOT NULL,
371	                          guest_email TEXT NOT NULL,
372	                          guest_cpf TEXT NOT NULL,
373	                          check_in DATE NOT NULL,
374	                          check_out DATE NOT NULL,
375	                          guests INTEGER NOT NULL,
376	                          rate_plan TEXT NOT NULL,
377	                          company_code TEXT,
378	                          nights INTEGER NOT NULL,
379	                          subtotal NUMERIC(12,2) NOT NULL,
380	                          discount NUMERIC(12,2) NOT NULL,
381	                          total NUMERIC(12,2) NOT NULL,
382	                          status TEXT NOT NULL,
383	                          amount_paid NUMERIC(12,2) NOT NULL,
384	                          refund NUMERIC(12,2))""");
385	                s.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations(room_number, check_in)");
386	                s.execute("""
387	                        CREATE TABLE IF NOT EXISTS messages (
388	                          id BIGSERIAL PRIMARY KEY,
389	                          channel TEXT NOT NULL,
390	                          recipient TEXT NOT NULL,
391	                          subject TEXT NOT NULL,
392	                          body TEXT NOT NULL)""");
393	                int[] numbers = {101, 102, 201, 202, 301};
394	                RoomType[] types = {RoomType.STANDARD, RoomType.STANDARD, RoomType.DELUXE, RoomType.DELUXE, RoomType.SUITE};
395	                for (int i = 0; i < numbers.length; i++) {
396	                    s.execute("INSERT INTO rooms(number,type,capacity,nightly_rate) VALUES (" + numbers[i] + ",'"
397	                            + types[i].name() + "'," + types[i].capacity + "," + types[i].nightlyRate
398	                            + ") ON CONFLICT (number) DO NOTHING");
399	                }
400	            }
401	            return null;
402	        });
403	    }
404	}

