     9	public final class Money {
    10	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    11	    private static final DecimalFormatSymbols BR = symbols();
    12	
    13	    private Money() {}
    14	
    15	    private static DecimalFormatSymbols symbols() {
    16	        DecimalFormatSymbols s = new DecimalFormatSymbols(Locale.ROOT);
    17	        s.setGroupingSeparator('.');
    18	        s.setDecimalSeparator(',');
    19	        return s;
    20	    }
