     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Seasons {
     8	    private Seasons() {}
     9	
    10	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
    11	    public static boolean isHigh(LocalDate night) {
    12	        Month m = night.getMonth();
    13	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    14	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    15	    }
    16	
    17	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    18	        return isHigh(night) ? Money.percent(room.nightlyRate(), "1.20") : room.nightlyRate();
    19	    }
    20	
    21	    /** Soma das noites [checkIn, checkOut), cada uma arredondada a centavos. */
    22	    public static BigDecimal sumNights(Room room, LocalDate checkIn, LocalDate checkOut) {
    23	        BigDecimal sum = Money.ZERO;
    24	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    25	            sum = sum.add(nightPrice(room, d));
    26	        }
    27	        return Money.round(sum);
    28	    }
    29	}
