 1	package com.marealta;
 2	
 3	import static org.junit.jupiter.api.Assertions.*;
 4	
 5	import com.marealta.plan.BookingTerms;
 6	import com.marealta.plan.Quote;
 7	import com.marealta.plan.RatePlans;
 8	import java.math.BigDecimal;
 9	import java.time.LocalDate;
10	import org.junit.jupiter.api.Test;
11	
12	class PricingTest {
13	    private static final Room STANDARD = new Room(101, RoomType.STANDARD, 2, RoomType.STANDARD.nightlyRate);
14	    private static final Room DELUXE = new Room(201, RoomType.DELUXE, 3, RoomType.DELUXE.nightlyRate);
15	
16	    private static Quote quote(String plan, Room room, String in, String out, String company) {
17	        return RatePlans.require(plan).quote(
18	                new BookingTerms(room, LocalDate.parse(in), LocalDate.parse(out), company));
19	    }
20	
21	    private static BigDecimal m(String v) { return Money.of(v); }
22	
23	    @Test void highSeasonNights() {
24	        Quote q = quote("STANDARD", STANDARD, "2027-07-10", "2027-07-12", null);
25	        assertEquals(m("599.76"), q.total());
26	        assertEquals(2, q.nights());
27	    }
28	
29	    @Test void seasonBoundaries() {
30	        assertFalse(Seasons.isHigh(LocalDate.parse("2027-12-14")));
31	        assertTrue(Seasons.isHigh(LocalDate.parse("2027-12-15")));
32	        assertTrue(Seasons.isHigh(LocalDate.parse("2028-02-29")));
33	        assertFalse(Seasons.isHigh(LocalDate.parse("2028-03-01")));
34	    }
35	
36	    @Test void corporate() {
37	        Quote q = quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", "TECNOSUL");
38	        assertEquals(m("779.80"), q.subtotal());
39	        assertEquals(m("93.58"), q.discount());
40	        assertEquals(m("686.22"), q.total());
41	    }
42	
43	    @Test void corporateNeedsKnownCompany() {
44	        assertThrows(ApiException.class, () -> quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", null));
45	        assertThrows(ApiException.class, () -> quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", "ACME"));
46	    }
47	
48	    @Test void weekendPackage() {
49	        Quote q = quote("WEEKEND_PACKAGE", DELUXE, "2027-03-12", "2027-03-14", null);
50	        assertEquals(m("820.00"), q.total());
51	        assertEquals(m("0.00"), q.discount());
52	        assertEquals(m("410.00"), RatePlans.require("WEEKEND_PACKAGE").refund(q.total()));
53	        assertThrows(ApiException.class, () -> quote("WEEKEND_PACKAGE", DELUXE, "2027-03-13", "2027-03-15", null));
54	        assertThrows(ApiException.class, () -> quote("WEEKEND_PACKAGE", DELUXE, "2027-03-12", "2027-03-15", null));
55	    }
56	
57	    @Test void longStay() {
58	        Quote q = quote("LONG_STAY", STANDARD, "2027-03-01", "2027-03-08", null);
59	        assertEquals(m("1749.30"), q.subtotal());
60	        assertEquals(m("174.93"), q.discount());
61	        assertEquals(m("1574.37"), q.total());
62	        assertThrows(ApiException.class, () -> quote("LONG_STAY", STANDARD, "2027-03-01", "2027-03-07", null));
63	    }
64	
65	    @Test void nonRefundable() {
66	        Quote q = quote("NON_REFUNDABLE", STANDARD, "2027-03-01", "2027-03-03", null);
67	        assertEquals(m("499.80"), q.subtotal());
68	        assertEquals(m("74.97"), q.discount());
69	        assertEquals(m("0.00"), RatePlans.require("NON_REFUNDABLE").refund(q.total()));
70	    }
71	
72	    @Test void receiptText() {
73	        Receipt r = new Receipt(Receipt.TITLE, 7, "Carla Dias", "111.222.333-44", 201, "DELUXE",
74	                "2027-03-10", "2027-03-12", 2, m("779.80"), m("0.00"), m("779.80"));
75	        assertEquals("""
76	                Comprovante de reserva nº 7
77	                Hóspede: Carla Dias (CPF 111.222.333-44)
78	                Quarto: 201 (DELUXE)
